/// <summary>
/// PricingAttribute of table <c>WHSCustTable</c> field FulfillmentPolicy.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(WHSCustTable, FulfillmentPolicy))]
internal class GUPPricingAttributeWHSCustTableFulfillmentPolicy extends GUPPricingAttributeWHSCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSCustTable, FulfillmentPolicy);
}

public str getRefValue(Str _defaultValue)
{
    WHSFulfillmentPolicy fulfillmentPolicy;
    str ret = "";
    boolean isFirstAttributeToAppend = true;
    Query query = new Query();
    query.addDataSource(tableNum(WHSFulfillmentPolicy)).addRange(fieldNum(WHSFulfillmentPolicy, RecId)).value(_defaultValue);
    QueryRun qr = new QueryRun(query);
    while (qr.next())
    {
        fulfillmentPolicy = qr.get(tableNum(WHSFulfillmentPolicy), 1);
        if (!isFirstAttributeToAppend)
        {
            ret += ",";
        }
        else
        {
            isFirstAttributeToAppend = false;
        }
        ret += fulfillmentPolicy.name;
    }

    return ret;
}

public boolean validate(Str _defaultValue)
{
    var recId = str2Int64(_defaultValue);
    return WHSFulfillmentPolicy::find(recId) ? true : false;
}

public void lookupAllowedValues(object _formStringControl)
{
    GUPFulfillmentPolicyLookup fulfillmentPolicyLookup = new GUPFulfillmentPolicyLookup(true);
    fulfillmentPolicyLookup.performLookup(_formStringControl);
}
